'use strict';
function actionBlendWeight(b,t){const input=b.blendIn??.2,output=b.blendOut??.2,start=b.start-input/2,end=b.start+b.duration+output/2;if(t<start||t>end)return 0;const smooth=f=>{f=clamp(f,0,1);return f*f*(3-2*f)};return Math.min(input>0?smooth((t-start)/input):t>=b.start?1:0,output>0?smooth((end-t)/output):t<=b.start+b.duration?1:0)}
function actionPoseSample(type,f,base){const v={...base};if(type==='wave'){v.rightArm=-140;v.rightElbow=-35+Math.sin(f*Math.PI*6)*22}else if(type==='point'){v.rightArm=-95;v.rightElbow=-5;v.handOpen=1}else if(type==='jump'){const height=Math.sin(f*Math.PI);v.y-=height*65;v.leftKnee+=height*35;v.rightKnee+=height*35;v.leftArm+=height*40;v.rightArm-=height*40}else if(type==='sit'){v.y+=34;v.leftLeg-=65;v.rightLeg-=65;v.leftKnee+=90;v.rightKnee+=90}else if(type==='talk'){v.rightArm-=25+Math.sin(f*Math.PI*5)*10;v.rightElbow-=25;v.headTilt+=Math.sin(f*Math.PI*4)*4;v.handOpen=1}return v}
function evaluateCharacterActions(o,t,v){const blocks=(o.actionBlocks||[]).slice().sort((a,b)=>a.start-b.start),walk=blocks.filter(b=>b.type==='walk'&&b.start<=t).at(-1);if(walk&&!(o.keys||[]).some(k=>k.t>walk.start+walk.duration&&k.t<=t)){const f=clamp((t-walk.start)/walk.duration,0,1),move=walk.travelEase==='linear'?f:f*f*(3-2*f);v.x=walk.from.x+(walk.to.x-walk.from.x)*move;v.y=walk.from.y+(walk.to.y-walk.from.y)*move;if(f>0&&f<1){const gait=Math.min(1,(t-walk.start)/Math.max(.01,walk.blendIn??.2),(walk.start+walk.duration-t)/Math.max(.01,walk.blendOut??.2)),dx=walk.to.x-walk.from.x,dy=walk.to.y-walk.from.y,distance=Math.hypot(dx,dy);if(typeof applyWalkingPose==='function'&&canAnimateWalk(o))applyWalkingPose(o,v,t-walk.start,{weight:gait,distance:distance*move,direction:distance?{x:dx/distance,y:dy/distance}:{x:1,y:0}});else{const cycle=(t-walk.start)*Math.PI*3.2;v.leg+=Math.sin(cycle)*23*gait;v.leftArm+=Math.sin(cycle)*24*gait;v.rightArm-=Math.sin(cycle)*24*gait;v.y-=Math.abs(Math.sin(cycle))*4*gait}}}
 const base={...v},active=blocks.filter(b=>b.type!=='walk').map(b=>({block:b,weight:actionBlendWeight(b,t)})).filter(b=>b.weight>0),total=active.reduce((n,b)=>n+b.weight,0),baseWeight=Math.max(0,1-total),divisor=Math.max(1,total);if(!active.length)return v;const sum={};for(const key of Object.keys(rigDefaults).concat(['leftArm','leftElbow','rightArm','rightElbow','leg','y']))sum[key]=base[key]*baseWeight;for(const {block:b,weight}of active){const f=clamp((t-b.start)/b.duration,0,1),sample=actionPoseSample(b.type,f,base);for(const key of Object.keys(sum))sum[key]+=sample[key]*weight}for(const key of Object.keys(sum))v[key]=sum[key]/divisor;return v}
const controlsBeforeBlends=renderControls;renderControls=function(){controlsBeforeBlends();const o=object();if(!isAnimatedCharacter(o))return;const block=(o.actionBlocks||[]).find(b=>b.id===selectedActionId),box=$('selectedActionControls');if(!block||!box)return;const controls=document.createElement('div');controls.innerHTML='<label>Blend in (s)<input id="actionBlendIn" type="number" min="0" max="2" step="0.05"></label><label>Blend out (s)<input id="actionBlendOut" type="number" min="0" max="2" step="0.05"></label><button id="blendAllCharacterActions">Smooth all actions</button><p class="note">Adjacent actions crossfade across their boundary. Set zero for a hard change. Blends do not move clips or audio.</p>';box.append(controls);for(const[id,key]of[['actionBlendIn','blendIn'],['actionBlendOut','blendOut']]){$(id).value=block[key]??.2;$(id).disabled=!!o.locked;$(id).onchange=e=>{if(o.locked)return;block[key]=clamp(+e.target.value||0,0,2);save();draw()}}$('blendAllCharacterActions').disabled=!!o.locked;$('blendAllCharacterActions').onclick=()=>{if(o.locked)return;for(const b of o.actionBlocks||[]){b.blendIn=Math.min(.3,b.duration/3);b.blendOut=Math.min(.3,b.duration/3)}save();render()}};
const validBeforeBlends=valid;valid=function(p){return validBeforeBlends(p)&&p.scenes.every(s=>s.objects.every(o=>(o.actionBlocks||[]).every(b=>['blendIn','blendOut'].every(k=>b[k]===undefined||Number.isFinite(b[k])&&b[k]>=0&&b[k]<=2))))};
render();
